package com.procurement.controller; import com.procurement.entity.*; import com.procurement.service.CatalogService; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1") public class CatalogController { private final CatalogService s; public CatalogController(CatalogService s){this.s=s;} @GetMapping("/crops") public List<Crop> crops(){return s.crops();} @GetMapping("/seasons") public List<ProcurementSeason> seasons(){return s.seasons();} @GetMapping("/centres") public List<ProcurementCentre> centres(){return s.centres();} @GetMapping("/centres/{id}") public ProcurementCentre centre(@PathVariable Long id){return s.centre(id);} @GetMapping("/schedules") public List<ProcurementSchedule> schedules(@RequestParam(required=false)Long centreId,@RequestParam(required=false)Long cropId,@RequestParam(required=false)LocalDate date){return s.schedules(centreId,cropId,date);} @GetMapping("/seasons/{id}/crops") public List<Crop> seasonCrops(@PathVariable Long id){return s.seasonCrops(id);} }
